clc, clear, close('all')% Specify the model namemodel = 'linear_system';% Specify the analysis I/Os% Get the analysis I/Os from the modelio = getlinio(model);% Specify the operating point% Use the model initial conditionop = operpoint(model);% Linearize the modelsys = linearize(model,io,op);% Plot the resulting linearizationfigure("WindowStyle","docked", Name='step_responce')step(sys)% Plot Bodefigure("WindowStyle","docked", Name='bode')bode(sys)